// SPDX-License-Identifier: MIT
pragma solidity ^0.8.33;

import {AdjudicatorBase} from "./AdjudicatorBase.sol";
import {ITruthMarket} from "../interfaces/ITruthMarket.sol";
import {
    IPrimusZKTLS,
    Attestation,
    AttNetworkRequest,
    AttNetworkResponseResolve
} from "./primus/IPrimusZKTLS.sol";

/// @notice Primus zkTLS resolution profile for one node.
/// @dev Re-expresses the four checks of Tora-Build/sooth-core
///      `src/adjudicators/ZkTLSAdjudicator.sol` at 5a22286 (signature, URL, data,
///      time) on this repository's lifecycle:
///        resolver proposes (outcome, keccak256(data))  ->  resolve()
///        anyone submits the Primus attestation         ->  attest()
///        guardian veto window, then                    ->  settle()
///      What the attestation proves: this request returned this data at this time. It
///      does NOT prove the outcome. Mapping data to YES/NO is the resolver's claim,
///      checked by guardians during the veto window, which runs from attest().
///      A market commits to the whole proof specification, not the URL alone. Primus
///      signs keccak256(abi.encodePacked(url, header, method, body)) with no length
///      delimiters, so a URL hash by itself is only a prefix check: bytes can move from
///      `url` into `header` (and from `data` into `attConditions`) under one signature.
contract ZkTLSAdjudicator is AdjudicatorBase {
    struct Source {
        bytes32 specHash; // see specHash()
        uint64 maxAge; // seconds before the market deadline; never zero
    }

    IPrimusZKTLS public immutable primusVerifier;
    /// Primus SDK timestamps are JavaScript milliseconds. Divide before comparing
    /// with block time. Set to 1 if a deployment's attestor signs seconds.
    uint64 public immutable timestampDivisor;
    mapping(address => Source) public sources;

    error InvalidSource();
    error InvalidSpec();
    error InvalidData();
    error StaleAttestation();

    constructor(
        address owner_,
        address marketFactory_,
        uint48 vetoPeriod_,
        address primusVerifier_,
        uint64 timestampDivisor_
    ) AdjudicatorBase(owner_, marketFactory_, vetoPeriod_) {
        require(
            primusVerifier_.code.length != 0 && vetoPeriod_ > 0 && timestampDivisor_ != 0,
            InvalidSource()
        );
        primusVerifier = IPrimusZKTLS(primusVerifier_);
        timestampDivisor = timestampDivisor_;
    }

    function adjudicatorType() external pure override returns (string memory) {
        return "zktls-primus";
    }

    /// @notice The proof specification a market commits to at creation.
    /// @dev ABI encoding is length-delimited, unlike Primus's packed signing hash.
    function specHash(
        AttNetworkRequest memory request,
        AttNetworkResponseResolve[] memory responseResolve,
        string memory attConditions
    ) public pure returns (bytes32) {
        return keccak256(abi.encode(request, responseResolve, attConditions));
    }

    /// @dev typeConfig is abi.encode(bytes32 specHash, uint64 maxAge).
    function _onConfigure(address market, bytes memory config) internal override {
        (bytes32 spec, uint64 maxAge) = abi.decode(config, (bytes32, uint64));
        require(spec != bytes32(0) && maxAge != 0, InvalidSource());
        sources[market] = Source(spec, maxAge);
    }

    function _verifyAttestation(address market, bytes calldata proof)
        internal
        view
        override
    {
        Attestation memory att = abi.decode(proof, (Attestation));
        primusVerifier.verifyAttestation(att);
        Source memory src = sources[market];
        MarketState storage st = _markets[market];
        require(
            specHash(att.request, att.reponseResolve, att.attConditions) == src.specHash,
            InvalidSpec()
        );
        require(keccak256(bytes(att.data)) == st.dataHash, InvalidData());
        uint256 at = uint256(att.timestamp) / timestampDivisor;
        require(at <= st.deadline, DeadlinePassed());
        uint256 earliest = st.deadline > src.maxAge ? st.deadline - src.maxAge : 0;
        require(at >= earliest, StaleAttestation());
    }

    function _requiresAttestation() internal pure override returns (bool) {
        return true;
    }
}

