// SPDX-License-Identifier: MIT
pragma solidity ^0.8.33;

import {AdjudicatorBase} from "./AdjudicatorBase.sol";
import {IMDAttestation} from "./IMDAttestation.sol";
import {ITruthMarket} from "../interfaces/ITruthMarket.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";

/// @notice IdentityMD Oracle v2 resolution profile for one node.
/// @dev Uses the base lifecycle unchanged, like the zkTLS profile:
///        resolver proposes (outcome, certificate digest)  ->  resolve()
///        anyone submits IMD's signed certificate          ->  attest()
///        guardian veto window from attest(), then         ->  settle()
///      The market's question string must be IMD's canonical question JSON, so
///      `TruthMarket.questionHash()` equals the `questionHash` IMD signs:
///        keccak256 of the key-sorted, whitespace-free JSON of
///        {v, question, chainId, window:{fromBlock,toBlock}, answerType, evidence,
///         definitions?}
///      (derived from live requests on 2026-10-11; IMD does not document it). The
///      request must name an explicit block window, otherwise IMD pins one and the
///      hash cannot be known at creation. Nothing is registered: a certificate is
///      bound to its market by that hash alone, so the resolver can only relay.
///      Unless the profile allows early resolution, the certificate must also be
///      issued at or after the market deadline. `guards` and `toleranceBps` are not
///      in IMD's hash: source rules a market relies on belong in `definitions`.
///      Replaces the request-registration design ported from sooth-core 96d5027.
///      The attester is immutable: rotating it means a new profile and admission.
contract IMDAdjudicator is AdjudicatorBase, EIP712 {
    uint8 private constant ANSWER_UINT256 = 3;

    address public immutable attester;
    uint16 public immutable panelSize;
    uint16 public immutable quorum;
    uint64 public immutable maxValidity;
    /// Certificate digests a guardian veto has rejected, per market.
    mapping(address => mapping(bytes32 => bool)) public rejected;

    error InvalidPolicy();
    error InvalidBinding();
    error InvalidCertificate();
    error RejectedCertificate();

    constructor(
        address owner_,
        address marketFactory_,
        uint48 vetoPeriod_,
        address attester_,
        uint16 panelSize_,
        uint16 quorum_,
        uint64 maxValidity_
    )
        AdjudicatorBase(owner_, marketFactory_, vetoPeriod_)
        EIP712("IdentityMD Oracle", "2")
    {
        require(
            attester_ != address(0) && vetoPeriod_ > 0 && panelSize_ >= 5
                && panelSize_ <= 100 && quorum_ > panelSize_ / 2 && quorum_ <= panelSize_
                && maxValidity_ >= 60 && maxValidity_ <= 30 days,
            InvalidPolicy()
        );
        attester = attester_;
        panelSize = panelSize_;
        quorum = quorum_;
        maxValidity = maxValidity_;
    }

    function adjudicatorType() external pure override returns (string memory) {
        return "imd-v2";
    }

    /// @notice The EIP-712 digest IMD signs for `cert` with this profile as consumer.
    /// @dev This is the `dataHash` the resolver passes to `resolve`.
    function certificateDigest(IMDAttestation.Certificate calldata cert)
        external
        view
        returns (bytes32)
    {
        return _hashTypedDataV4(IMDAttestation.structHash(cert));
    }

    /// @dev typeConfig is abi.encode(bytes32 imdQuestionHash) and must equal the
    ///      market's own question hash.
    function _onConfigure(address market, bytes memory config) internal view override {
        bytes32 questionHash = abi.decode(config, (bytes32));
        require(
            questionHash != bytes32(0)
                && questionHash == ITruthMarket(market).questionHash(),
            InvalidBinding()
        );
    }

    function _onResolve(address market, uint8, bytes32 dataHash) internal view override {
        require(dataHash != bytes32(0), InvalidCertificate());
        require(!rejected[market][dataHash], RejectedCertificate());
    }

    function _verifyAttestation(address market, bytes calldata proof)
        internal
        view
        override
    {
        (IMDAttestation.Certificate memory cert, bytes memory signature) =
            abi.decode(proof, (IMDAttestation.Certificate, bytes));
        MarketState storage st = _markets[market];
        bytes32 digest = _hashTypedDataV4(IMDAttestation.structHash(cert));
        require(
            digest == st.dataHash
                && cert.questionHash == ITruthMarket(market).questionHash()
                && cert.blockHash != bytes32(0) && cert.answerType == ANSWER_UINT256
                && cert.answer.length == 32 && cert.panelSize == panelSize
                && cert.quorum == quorum && cert.agreed >= quorum
                && cert.agreed <= panelSize,
            InvalidCertificate()
        );
        require(
            cert.issuedAt <= block.timestamp && cert.expiresAt > block.timestamp
                && cert.expiresAt > cert.issuedAt
                && cert.expiresAt - cert.issuedAt <= maxValidity,
            InvalidCertificate()
        );
        // An answer given before the deadline is not an answer about the outcome.
        // Without this the resolver, who cannot change the answer, could still
        // choose when to ask.
        require(earlyResolution || cert.issuedAt >= st.deadline, InvalidCertificate());
        require(abi.decode(cert.answer, (uint256)) == st.outcome, InvalidCertificate());
        require(ECDSA.recover(digest, signature) == attester, InvalidCertificate());
    }

    /// @dev A vetoed certificate can never be proposed for this market again; a
    ///      second round needs a fresh IMD request, which signs a new digest.
    function _onDispute(address market) internal override {
        MarketState storage st = _markets[market];
        rejected[market][st.dataHash] = true;
        st.dataHash = bytes32(0);
    }

    function _requiresAttestation() internal pure override returns (bool) {
        return true;
    }
}

